function typologyGroup(name){return ONT_TYPOLOGY_GROUPS.find(g=>g.name===name)}
function complementaryDetail(c){return ONT_COMPLEMENTARY_DETAILS[c?.typologyCode]||null}
function isLinearUnit(c){const d=complementaryDetail(c);return ['m','ML','km'].includes(d?.unit||c?.quantityUnit)||['Cerca','Tapia','Verja','Muro'].includes(c?.category)}
function isFieldElement(c){return isLinearUnit(c)||['Gavión','Losa','Obra exterior','Obra vial complementaria','Rampa','Portón','Poste'].includes(c?.category)}

