async function openDb(){return new Promise((resolve,reject)=>{try{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const d=req.result;if(!d.objectStoreNames.contains(STORE_CASES)){const s=d.createObjectStore(STORE_CASES,{keyPath:'id'});s.createIndex('updatedAt','updatedAt')}if(!d.objectStoreNames.contains(STORE_PHOTOS)){const s=d.createObjectStore(STORE_PHOTOS,{keyPath:'id'});s.createIndex('caseId','caseId')}};req.onsuccess=()=>{db=req.result;storageMode='indexeddb';resolve(db)};req.onerror=()=>reject(req.error||new Error('IndexedDB no disponible'));req.onblocked=()=>reject(new Error('La base local está bloqueada por otra pestaña'))}catch(error){reject(error)}});}
function memoryStore(store){return memoryDb[store]||memoryDb.cases}
function idbPut(store,val){if(!db||storageMode==='memory'){storageMode='memory';memoryStore(store).set(val.id,val);return Promise.resolve()}return new Promise((res,rej)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(val);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)});}
