function handleBoundInput(e){const el=e.target;ensureCaptureStarted();if(el.dataset.path){let v=el.type==='checkbox'?el.checked:el.value;setPath(state.current,el.dataset.path,v);if(el.dataset.path==='visit.date'){state.current.visit.day=dayName(v);const dayEl=document.querySelector('[data-path="visit.day"]');if(dayEl)dayEl.value=state.current.visit.day}markDirty()}else if(el.dataset.array){let arr=getPath(state.current,el.dataset.array)||[];arr=el.checked?[...new Set([...arr,el.value])]:arr.filter(x=>x!==el.value);setPath(state.current,el.dataset.array,arr);markDirty()}}

