function cField(label,key,c,cls){return `<label class="field ${cls}"><span>${label}</span><input data-c-key="${key}" value="${esc(c[key]??'')}"></label>`}
function cNum(label,key,c,step,cls,readOnly=false){return `<label class="field ${cls}"><span>${label}</span><input type="number" step="${step}" data-c-key="${key}" value="${esc(c[key]??'')}" ${readOnly?'readonly aria-readonly="true" title="Se calcula con la suma de los tramos del croquis"':''}></label>`}
function cSelect(label,key,c,opts,cls){return `<label class="field ${cls}"><span>${label}</span><select data-c-key="${key}"><option value="">Seleccione</option>${opts.map(o=>`<option value="${esc(o)}" ${c[key]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`}
function cSelectOther(label,key,otherKey,c,opts,cls){const show=c[key]==='Otro — especificar';return `<label class="field ${cls}"><span>${label}</span><select data-c-key="${key}" data-other-key="${otherKey}"><option value="">Seleccione</option>${opts.map(o=>`<option value="${esc(o)}" ${c[key]===o?'selected':''}>${esc(o)}</option>`).join('')}</select>${show?`<input data-c-key="${otherKey}" value="${esc(c[otherKey]||'')}" placeholder="Especifique" style="margin-top:7px">`:''}</label>`}
function cTypologyFamily(c){return `<label class="field col-6"><span>Familia de tipología ONT 2023 + ampliación 2025</span><select data-c-key="typologyFamily"><option value="">Seleccione</option>${ONT_TYPOLOGY_GROUPS.map(g=>`<option value="${esc(g.name)}" ${c.typologyFamily===g.name?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label>`}
function applyLinearDefaults(c){if(!isLinearUnit(c))return;c.walls=c.walls||'No aplica';c.wallFinish=c.wallFinish||'No aplica';if(!c.linearDescription)c.linearDescription={Cerca:'Cerca',Tapia:'Tapia',Verja:'Verja',Muro:'Muro'}[c.category]||''}
function handleConstructionInput(e){const card=e.currentTarget;const c=state.current.constructions.find(x=>x.id===card.dataset.id);const key=e.target.dataset.cKey;if(!c||!key)return;c[key]=e.target.value;if(key==='category'){applyLinearDefaults(c);markDirty();renderConstructions();return}if(key==='typologyFamily'){const familyDefaults=[['Cercas','Cerca','ML'],['Tapias','Tapia','ML'],['Verjas','Verja','ML'],['Muros','Muro','ML'],['Losas','Losa','m²'],['Obras exteriores','Obra exterior','m²'],['Obras viales','Obra vial complementaria','ML'],['Rampas','Rampa','m²'],['Portones','Portón','unidad'],['Postes','Poste','unidad']];const fd=familyDefaults.find(x=>c.typologyFamily.includes(x[0]));if(fd){c.category=fd[1];c.quantityUnit=fd[2]}else{c.category='Construcción';c.quantityUnit='m²'}applyLinearDefaults(c);markDirty();renderConstructions();return}if(key==='quantityUnit'){if(isLinearUnit(c)){applyLinearDefaults(c);prepareLinearSketch(c)}else if(activePolygon(normalizeManualSketch(c.handSketch)).linear)c.handSketch=blankManualSketch();markDirty();renderConstructions();return}if(key==='zocalo'){markDirty();renderConstructions();return}if(e.target.dataset.otherKey){markDirty();renderConstructions();return}markDirty();if(key==='name'){const title=card.querySelector('.construction-title-input');if(title&&title!==e.target)title.value=c.name||''}if(key==='linearDescription'||key==='linearDescriptionOther')renderConstructions();refreshDerived()}
function selectedValue(c,key){return c[key]==='Otro — especificar'?(c[`${key}Other`]||'Otro'):c[key]||''}
// El mismo módulo de croquis admite polilíneas ML de dos o más vértices.
const DEFAULT_SEGMENT_DETAILS=['Frente','Fondo','Lateral','Corredor','Cochera','Otro'];
function blankPolygonSketch(){return{linear:false,points:[],closed:false,segments:[],finalized:false,area:0,perimeter:0,metricPoints:[],adjustmentMessage:''}}
