  const norm=e=>{const r=canvas.getBoundingClientRect();return{x:Math.max(.02,Math.min(.98,(e.clientX-r.left)/r.width)),y:Math.max(.05,Math.min(.96,(e.clientY-r.top)/r.height))}},nearest=(poly,p)=>{let best=-1,d=.05;poly.points.forEach((q,i)=>{const z=Math.hypot(q.x-p.x,q.y-p.y);if(z<d){d=z;best=i}});return best};
