        const last=poly.points.at(-1),prev=poly.points.at(-2);let dx=last.x-prev.x,dy=last.y-prev.y,len=Math.hypot(dx,dy)||.2;dx=dx/len*.18;dy=dy/len*.18;let x=last.x+dx,y=last.y+dy;if(x>.94||x<.06||y>.90||y<.12){const tx=-dy,ty=dx;x=last.x+tx;y=last.y+ty}x=Math.max(.06,Math.min(.94,x));y=Math.max(.12,Math.min(.90,y));poly.points.push({x,y,label:`V${poly.points.length+1}`});poly.draftSideCount=poly.points.length;syncManualSegments(poly);poly.segments.at(-1).note=description();invalidateLinearCalculation(poly);updateConstructionTotal(poly);changed();toast(`Vértice agregado: ${poly.points.length}`)
