function bindConstructionSketch(card,c){const linear=isLinearUnit(c);if(linear){applyLinearDefaults(c);prepareLinearSketch(c)}else{c.handSketch=normalizeManualSketch(c.handSketch);if(activePolygon(c.handSketch).linear)c.handSketch=blankManualSketch()}const normalized=bindManualSketch(card,c.handSketch,()=>markDirty(),`${safeName()}_${(c.name||'unidad').replace(/[^a-z0-9]+/gi,'_')}_croquis.png`,c.name||'Croquis de construcción',()=>syncConstructionAreaFromSketch(c),{linear,description:()=>linearElementLabel(c),construction:c});c.handSketch=normalized}

function refreshAssociationSelectors(){if(!state.current)return;for(const id of ['photoConstructionId']){const el=$(`#${id}`);if(!el)continue;const current=el.value;el.innerHTML='<option value="">Seleccione construcción</option>';state.current.constructions.forEach((c,i)=>{const o=document.createElement('option');o.value=c.id;o.textContent=`Unidad ${i+1} — ${c.name||'Sin nombre'}`;el.appendChild(o)});if([...el.options].some(o=>o.value===current))el.value=current}togglePhotoConstruction()}
function togglePhotoConstruction(){const field=$('#photoConstructionField');if(field)field.classList.remove('hidden-field')}
$('#addConstructionBtn').addEventListener('click',()=>{const wasEmpty=!hasRegisteredConstructions(),c=blankConstruction();c.name=`Unidad ${state.current.constructions.length+1}`;state.current.constructions.push(c);if(wasEmpty)CONSTRUCTION_FISCAL_KEYS.forEach(k=>state.current.report.fiscalization[k]='');markDirty();renderConstructions();refreshDerived();setTimeout(()=>$('#constructionList').lastElementChild?.scrollIntoView({behavior:'smooth'}),50)});

// Geodesia: CR-SIRGAS / CRTM05 (EPSG:8908). El dispositivo entrega WGS84 y se aplica la transformación oficial IGN/SNIT.
const ELL_WGS84={a:6378137,invF:298.257223563};
const ELL_GRS80={a:6378137,invF:298.257222101};
for(const e of [ELL_WGS84,ELL_GRS80]){e.f=1/e.invF;e.e2=e.f*(2-e.f)}
const HELMERT_CR_TO_WGS={tx:.16959,ty:-.35312,tz:-.51846,rx:-.03385,ry:.16325,rz:-.03446,ppm:.03693};
const TM={a:ELL_GRS80.a,f:ELL_GRS80.f,k0:.9999,lon0:-84*Math.PI/180,lat0:0,E0:500000,N0:0};TM.e2=TM.f*(2-TM.f);TM.ep2=TM.e2/(1-TM.e2);
function geodeticToEcef(latDeg,lonDeg,h,ell){const p=latDeg*Math.PI/180,l=lonDeg*Math.PI/180,N=ell.a/Math.sqrt(1-ell.e2*Math.sin(p)**2);return{x:(N+h)*Math.cos(p)*Math.cos(l),y:(N+h)*Math.cos(p)*Math.sin(l),z:(N*(1-ell.e2)+h)*Math.sin(p)}}
function ecefToGeodetic(v,ell){const lon=Math.atan2(v.y,v.x),p=Math.hypot(v.x,v.y);let lat=Math.atan2(v.z,p*(1-ell.e2)),h=0;for(let i=0;i<10;i++){const N=ell.a/Math.sqrt(1-ell.e2*Math.sin(lat)**2);h=p/Math.cos(lat)-N;const next=Math.atan2(v.z,p*(1-ell.e2*N/(N+h)));if(Math.abs(next-lat)<1e-13){lat=next;break}lat=next}return{lat:lat*180/Math.PI,lon:lon*180/Math.PI,h}}
function helmert(v,p){const sec=Math.PI/(180*3600),rx=p.rx*sec,ry=p.ry*sec,rz=p.rz*sec,m=1+p.ppm*1e-6;return{x:p.tx+m*(v.x-rz*v.y+ry*v.z),y:p.ty+m*(rz*v.x+v.y-rx*v.z),z:p.tz+m*(-ry*v.x+rx*v.y+v.z)}}
function inverseHelmert(v,p){return helmert(v,{tx:-p.tx,ty:-p.ty,tz:-p.tz,rx:-p.rx,ry:-p.ry,rz:-p.rz,ppm:-p.ppm})}
function projectCrtm(latDeg,lonDeg){const a=TM.a,e2=TM.e2,ep2=TM.ep2,k0=TM.k0,p=latDeg*Math.PI/180,l=lonDeg*Math.PI/180,N=a/Math.sqrt(1-e2*Math.sin(p)**2),T=Math.tan(p)**2,C=ep2*Math.cos(p)**2,A=Math.cos(p)*(l-TM.lon0),M=a*((1-e2/4-3*e2**2/64-5*e2**3/256)*p-(3*e2/8+3*e2**2/32+45*e2**3/1024)*Math.sin(2*p)+(15*e2**2/256+45*e2**3/1024)*Math.sin(4*p)-(35*e2**3/3072)*Math.sin(6*p));return{easting:TM.E0+k0*N*(A+(1-T+C)*A**3/6+(5-18*T+T**2+72*C-58*ep2)*A**5/120),northing:TM.N0+k0*(M+N*Math.tan(p)*(A**2/2+(5-T+9*C+4*C**2)*A**4/24+(61-58*T+T**2+600*C-330*ep2)*A**6/720))}}
function inverseProjectCrtm(E,North){const a=TM.a,e2=TM.e2,ep2=TM.ep2,k0=TM.k0,M=(North-TM.N0)/k0,mu=M/(a*(1-e2/4-3*e2**2/64-5*e2**3/256)),e1=(1-Math.sqrt(1-e2))/(1+Math.sqrt(1-e2)),p1=mu+(3*e1/2-27*e1**3/32)*Math.sin(2*mu)+(21*e1**2/16-55*e1**4/32)*Math.sin(4*mu)+(151*e1**3/96)*Math.sin(6*mu)+(1097*e1**4/512)*Math.sin(8*mu),C1=ep2*Math.cos(p1)**2,T1=Math.tan(p1)**2,N1=a/Math.sqrt(1-e2*Math.sin(p1)**2),R1=a*(1-e2)/(1-e2*Math.sin(p1)**2)**1.5,D=(E-TM.E0)/(N1*k0),lat=p1-(N1*Math.tan(p1)/R1)*(D**2/2-(5+3*T1+10*C1-4*C1**2-9*ep2)*D**4/24+(61+90*T1+298*C1+45*T1**2-252*ep2-3*C1**2)*D**6/720),lon=TM.lon0+(D-(1+2*T1+C1)*D**3/6+(5-2*C1+28*T1-3*C1**2+8*ep2+24*T1**2)*D**5/120)/Math.cos(p1);return{lat:lat*180/Math.PI,lon:lon*180/Math.PI}}
function wgsToCrtm(latDeg,lonDeg){const w=geodeticToEcef(latDeg,lonDeg,0,ELL_WGS84),cr=inverseHelmert(w,HELMERT_CR_TO_WGS),geo=ecefToGeodetic(cr,ELL_GRS80);return projectCrtm(geo.lat,geo.lon)}
