  if(summary.totalCount){const cells=[`<div class="summary-cell total"><span>RESUMEN CONSTRUCTIVO</span><b>${summary.totalCount}</b><small>${summary.totalCount===1?'construcción declarada':'construcciones declaradas'}</small></div>`];if(summary.areaCount)cells.push(`<div class="summary-cell"><span>CONSTRUCCIONES EN m²</span><b>${summary.areaCount}</b><small>${summary.areaCount===1?'construcción':'construcciones'} · ${summary.area} m²</small></div>`);if(summary.linearCount)cells.push(`<div class="summary-cell"><span>CONSTRUCCIONES EN ML</span><b>${summary.linearCount}</b><small>${summary.linearCount===1?'construcción':'construcciones'} · ${summary.length} ML</small></div>`);sections.push(`<section class="report-section construction-summary"><h2>Resumen constructivo</h2><div class="construction-summary-d cols-${cells.length}">${cells.join('')}</div></section>`)}
  sections.push(`<section class="report-section photos-section"><h2>Registro fotográfico</h2>${photos.length?`<div class="photo-grid">${photos.map((p,i)=>`<figure><div class="photo-wrap"><img src="${p.dataUrl}"></div><figcaption>Fotografía ${i+1}. ${esc(p.constructionName||'Terreno')} · ${esc(p.category||'Vista general')}<br>${esc(new Date(p.capturedAt).toLocaleString('es-CR'))}</figcaption></figure>`).join('')}</div>`:'<p>Sin fotografías registradas.</p>'}</section>`);
  sections.push(`<section class="report-section field-responsible"><h2>Responsable de la fiscalización de campo</h2><div class="signature-panel-171"><div class="signature-data-171"><table class="responsible"><colgroup><col style="width:22%"><col style="width:78%"></colgroup><tr><th>Funcionario</th><td>${esc(reportValue(c.report.fieldProfessional))}</td></tr><tr><th>Puesto</th><td>${esc(reportValue(c.report.fieldPosition))}</td></tr><tr><th>Fecha y hora</th><td>${esc(`${reportValue(c.report.fieldDate)} · ${reportValue(c.report.fieldTime)}`)}</td></tr></table></div><div class="signature-area-171"><div class="signature-title-171">FIRMA</div><div class="signature-space-171">${c.report.fieldSignature?`<img class="sig" src="${c.report.fieldSignature}">`:''}</div><div class="signature-line-171"></div><div class="signature-help-171">Firma manuscrita o digital</div></div></div></section>`);
  const assessment=fiscalizationAssessment(f,c);f.decision=assessment.decision;const decision=reportDecisionLabel(f.decision),decisionClass=f.decision==='OBJETAR'?'reject':f.decision==='ACEPTAR'?'accept':'pending';
  sections.push(`<section class="report-section analysis-resolution"><h2>Análisis técnico de fiscalización</h2><div class="analysis-body"><p>De la revisión de la información consignada en la declaración presentada y de su contraste con las condiciones verificadas durante la inspección de campo, se determina lo siguiente:</p>${reportAnalysisRows(c)}</div><h2>Decisión administrativa</h2><div class="decision-strip ${decisionClass}"><b>${esc(decision)}</b><span>${esc(f.decision==='ACEPTAR'?'La Administración Tributaria Municipal acepta la información fiscalizada.':f.decision==='OBJETAR'?'La Administración Tributaria Municipal objeta la información fiscalizada hasta que se atiendan las diferencias registradas.':'Complete los criterios aplicables del formulario para determinar la decisión.')}</span></div><div class="analysis-grid"><div><h3>Motivación técnica</h3><p style="white-space:pre-line">${esc(fiscalizationMotivation(f,c))}</p></div><div><h3>Fundamento legal</h3><p>La decisión se emite con fundamento en la Ley N.° 7509, su Reglamento y las demás disposiciones aplicables al procedimiento de fiscalización, junto con los antecedentes técnicos incorporados al expediente.</p></div></div></section>`);
