async function openEditableReport(autoPrint=false){await saveCase(true);const html=await buildReportHtml();const w=window.open('','_blank');if(!w)return toast('Permita ventanas emergentes para abrir el informe');w.document.write(html);w.document.close();w.onload=()=>{w.document.title=`${safeName()}_informe`;if(autoPrint)setTimeout(()=>w.print(),500)}}
$('#completeCaseBtn').addEventListener('click',async()=>{const audit=runAudit();const critical=audit.filter(x=>x.level==='error');if(critical.length){renderAudit();showView('report');return toast(`No se puede finalizar: ${critical.length} error(es) pendiente(s).`)}state.current.status='Finalizado';state.current.completedAt=new Date().toISOString();await saveCase(true);renderCaseList();toast('Expediente finalizado y listo para exportar o enviar')});
$('#previewBtn').addEventListener('click',()=>openEditableReport(false));
$('#pdfBtn').addEventListener('click',()=>openEditableReport(true));
