function normalizeHeader(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
const IMPORT_ALIASES={
 tramite:['tramite','numero de tramite','expediente','numero expediente'],declarationDate:['fecha de declaracion','fecha declaracion','declaration date'],finca:['finca','matricula','numero de finca'],plano:['plano','plano catastrado'],registryArea:['area registro','area segun registro','area m2'],owner:['propietario','propietario registral','nombre propietario'],ownerId:['identificacion','cedula','id propietario'],processType:['tipo tramite','tipo de tramite'],observations:['observaciones','observacion','notas expediente','comentarios'],province:['provincia'],canton:['canton'],district:['distrito'],locality:['localidad'],date:['fecha inspeccion','dia inspeccion'],reference:['referencia','direccion','direccion exacta']};
function parseImportedDate(value){
  if(value==null||String(value).trim()==='')return'';
  const raw=String(value).trim();
  if(/^\d+(?:\.\d+)?$/.test(raw)){const serial=Number(raw);if(serial>20000&&serial<80000){const d=new Date(Date.UTC(1899,11,30)+Math.floor(serial)*86400000);return d.toISOString().slice(0,10)}}
  const iso=raw.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/);if(iso)return`${iso[1]}-${String(iso[2]).padStart(2,'0')}-${String(iso[3]).padStart(2,'0')}`;
  const local=raw.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})/);if(local)return`${local[3]}-${String(local[2]).padStart(2,'0')}-${String(local[1]).padStart(2,'0')}`;
  const parsed=new Date(raw);return Number.isNaN(parsed.getTime())?'':parsed.toISOString().slice(0,10)
}
