function csvRows(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(ch==='"'){if(q&&next==='"'){cell+='"';i++}else q=!q}else if(ch===','&&!q){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!q){if(ch==='\r'&&next==='\n')i++;row.push(cell);if(row.some(x=>String(x).trim()))rows.push(row);row=[];cell=''}else cell+=ch}row.push(cell);if(row.some(x=>String(x).trim()))rows.push(row);return rows}
async function unzipXlsx(buffer){const b=new Uint8Array(buffer),dv=new DataView(buffer);let eocd=-1;for(let i=b.length-22;i>=Math.max(0,b.length-66000);i--)if(dv.getUint32(i,true)===0x06054b50){eocd=i;break}if(eocd<0)throw new Error('Archivo XLSX no válido');const count=dv.getUint16(eocd+10,true),offset=dv.getUint32(eocd+16,true),files={};let p=offset;for(let n=0;n<count;n++){if(dv.getUint32(p,true)!==0x02014b50)break;const method=dv.getUint16(p+10,true),comp=dv.getUint32(p+20,true),nameLen=dv.getUint16(p+28,true),extra=dv.getUint16(p+30,true),comment=dv.getUint16(p+32,true),local=dv.getUint32(p+42,true),name=new TextDecoder().decode(b.slice(p+46,p+46+nameLen));const ln=dv.getUint16(local+26,true),le=dv.getUint16(local+28,true),data=b.slice(local+30+ln+le,local+30+ln+le+comp);let out;if(method===0)out=data;else if(method===8){if(!('DecompressionStream'in window))throw new Error('Este navegador no permite leer XLSX comprimido. Use CSV.');out=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer())}else throw new Error('Compresión XLSX no soportada');files[name]=out;p+=46+nameLen+extra+comment}return files}
async function xlsxRows(file){const files=await unzipXlsx(await file.arrayBuffer()),dec=new TextDecoder();const shared=[];if(files['xl/sharedStrings.xml']){const doc=new DOMParser().parseFromString(dec.decode(files['xl/sharedStrings.xml']),'application/xml');doc.querySelectorAll('si').forEach(si=>shared.push([...si.querySelectorAll('t')].map(t=>t.textContent).join('')))}const sheetName=Object.keys(files).find(x=>/^xl\/worksheets\/sheet\d+\.xml$/.test(x));if(!sheetName)throw new Error('No se encontró una hoja de datos');const doc=new DOMParser().parseFromString(dec.decode(files[sheetName]),'application/xml'),rows=[];doc.querySelectorAll('sheetData row').forEach(r=>{const arr=[];r.querySelectorAll('c').forEach(c=>{const ref=c.getAttribute('r')||'A1',col=ref.match(/[A-Z]+/)[0].split('').reduce((a,x)=>a*26+x.charCodeAt(0)-64,0)-1,type=c.getAttribute('t'),v=c.querySelector('v')?.textContent||'',inline=[...c.querySelectorAll('is t')].map(t=>t.textContent).join('');arr[col]=type==='s'?shared[Number(v)]||'':type==='inlineStr'?inline:v});rows.push(arr.map(x=>x??''))});return rows}
function rowsToObjects(rows){if(rows.length<2)return[];const heads=rows[0].map(x=>String(x||'').trim());return rows.slice(1).filter(r=>r.some(x=>String(x||'').trim())).map(r=>Object.fromEntries(heads.map((h,i)=>[h,r[i]??''])))}
async function importExcelFile(file){const ext=file.name.toLowerCase().split('.').pop();if(!['xlsx','csv'].includes(ext))throw new Error('Formato no permitido. Use XLSX o CSV.');const rows=ext==='csv'?csvRows(await file.text()):await xlsxRows(file);const objects=rowsToObjects(rows);if(!objects.length)throw new Error('El archivo no contiene filas de expedientes');let created=0,updated=0;const existing=await idbAll(STORE_CASES),byTramite=new Map(existing.filter(x=>String(x.general?.tramite||'').trim()).map(x=>[String(x.general.tramite).trim().toLocaleLowerCase('es-CR'),x]));for(const obj of objects){const c=mapImportedRow(obj);c.sourceFile=file.name;const key=String(c.general.tramite||'').trim().toLocaleLowerCase('es-CR'),found=key?byTramite.get(key):null;if(found){const merged=normalizeCase({...found,general:{...found.general,...c.general},visit:{...found.visit,...c.visit},location:{...found.location,...c.location},sourceFile:file.name,importedAt:new Date().toISOString()});await idbPut(STORE_CASES,merged);byTramite.set(key,merged);updated++}else{await idbPut(STORE_CASES,c);if(key)byTramite.set(key,c);created++}}await renderCaseList();return{created,updated,total:objects.length}}
$('#excelImport')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;const host=$('#excelImportResult');host.innerHTML='<div class="notice">Procesando archivo…</div>';try{const r=await importExcelFile(file);host.innerHTML=`<div class="notice ok"><b>Importación completada.</b> ${r.created} expedientes creados, ${r.updated} actualizados, ${r.total} filas procesadas.</div>`;toast('Expedientes importados correctamente')}catch(err){host.innerHTML=`<div class="notice danger"><b>Error:</b> ${esc(err.message)}</div>`}finally{e.target.value=''}});
$('#excelTemplateBtn')?.addEventListener('click',()=>{const bytes=makeXlsx([{name:'Expedientes',rows:[['Número de trámite','Fecha de declaración','Finca','Plano catastrado','Área según registro','Propietario registral','Identificación','Tipo de trámite','Observaciones','Provincia','Cantón','Distrito','Localidad','Fecha inspección','Dirección exacta'],['BI-2026-0001','','4-123456-000','H-1234567-2025',1250,'Nombre de ejemplo','1-0000-0000','Fiscalización','','Heredia','Sarapiquí','Puerto Viejo','La Guaria','','250 m norte de la escuela']]}]);downloadBlob(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),'Plantilla_Importacion_Expedientes.xlsx')});
function repositoryEndpoint(){return localStorage.getItem('fiscalizacion_repository_endpoint')||''}
function updateRepositoryUi(){const input=$('#repositoryEndpoint'),status=$('#repositoryStatus'),url=repositoryEndpoint();if(input)input.value=url;if(status)status.textContent=url?`Repositorio configurado: ${url}`:'Repositorio sin configurar.'}
$('#saveRepositoryBtn')?.addEventListener('click',()=>{const url=$('#repositoryEndpoint').value.trim();if(url&&!/^https:\/\//i.test(url))return toast('La dirección debe iniciar con https://');localStorage.setItem('fiscalizacion_repository_endpoint',url);updateRepositoryUi();toast('Dirección del repositorio guardada')});
async function enqueueCase(c,error=''){const q=JSON.parse(localStorage.getItem('fiscalizacion_send_queue')||'[]').filter(x=>x.caseId!==c.id);q.push({caseId:c.id,queuedAt:new Date().toISOString(),error});localStorage.setItem('fiscalizacion_send_queue',JSON.stringify(q));c.sendStatus='En cola';await idbPut(STORE_CASES,c)}
async function sendCurrentCase(){const c=state.current;if(c.status!=='Finalizado'&&c.status!=='Enviado')return toast('Finalice el expediente antes de enviarlo.');const url=repositoryEndpoint();if(!url||!navigator.onLine){await enqueueCase(c,!url?'Repositorio no configurado':'Sin conexión');renderCaseList();return toast('Expediente guardado en cola para envío.')}try{const photos=await photosForCase(c.id),payload={schema:'FiscalizacionMunicipal',version:APP_VERSION,sentAt:new Date().toISOString(),case:c,photos:photos.map(p=>({id:p.id,constructionId:p.constructionId,constructionName:p.constructionName,category:p.category,capturedAt:p.capturedAt,fileName:p.fileName}))};const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!res.ok)throw new Error(`Servidor respondió ${res.status}`);c.status='Enviado';c.sendStatus='Enviado';c.sentAt=new Date().toISOString();await idbPut(STORE_CASES,c);const q=JSON.parse(localStorage.getItem('fiscalizacion_send_queue')||'[]').filter(x=>x.caseId!==c.id);localStorage.setItem('fiscalizacion_send_queue',JSON.stringify(q));renderAll();renderCaseList();toast('Expediente enviado correctamente')}catch(err){await enqueueCase(c,err.message);renderCaseList();toast(`No se pudo enviar; quedó en cola: ${err.message}`)}}
$('#sendCurrentBtn')?.addEventListener('click',sendCurrentCase);
$('#sendQueueBtn')?.addEventListener('click',async()=>{const q=JSON.parse(localStorage.getItem('fiscalizacion_send_queue')||'[]');if(!q.length)return toast('No hay expedientes en cola.');for(const item of [...q]){const c=await idbGet(STORE_CASES,item.caseId);if(c){state.current=normalizeCase(c);await sendCurrentCase()}}toast('Revisión de la cola completada')});
function caseSortText(value){const text=String(value||'').trim();return text?text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es-CR'):'\uffff'}
function compareCasesByDistrictPlaceDate(a,b){const district=caseSortText(a.visit?.district).localeCompare(caseSortText(b.visit?.district),'es-CR',{sensitivity:'base',numeric:true});if(district)return district;const place=caseSortText(casePlace(a)).localeCompare(caseSortText(casePlace(b)),'es-CR',{sensitivity:'base',numeric:true});if(place)return place;const date=caseInspectionDate(b).localeCompare(caseInspectionDate(a));if(date)return date;return String(a.general?.tramite||a.general?.finca||'').localeCompare(String(b.general?.tramite||b.general?.finca||''),'es-CR',{sensitivity:'base',numeric:true})}
async function renderCaseList(){if(!db&&storageMode!=='memory')return;const host=$('#caseList');const all=(await idbAll(STORE_CASES)).sort(compareCasesByDistrictPlaceDate);host.innerHTML='';for(const c of all){const status=c.status||'Asignado',cls=status==='Finalizado'?'status-finalizado':status==='Enviado'?'status-enviado':status==='En proceso'?'status-proceso':'status-asignado',district=c.visit?.district||'Sin distrito',place=casePlace(c)||'Sin lugar',inspectionDate=caseInspectionDate(c)||'Sin fecha';const row=document.createElement('div');row.className='case-row';row.innerHTML=`<div><b>${esc(c.general?.tramite||'Sin número de trámite')}</b><span class="status-badge ${cls}">${esc(status)}</span><small>Finca: ${esc(c.general?.finca||'—')} · Plano: ${esc(c.general?.plano||'—')}<br>Distrito: ${esc(district)} · Lugar: ${esc(place)} · Fecha: ${esc(inspectionDate)}</small></div><div class="case-actions"><button class="btn primary small" data-open>Abrir</button><button class="btn pdf small" data-pdf>PDF</button><button class="btn secondary small" data-word>Word</button><button class="btn excel small" data-excel>Excel</button><button class="btn repository small" data-send>Enviar</button><button class="btn danger small" data-delete>Eliminar</button></div>`;row.querySelector('[data-open]').addEventListener('click',()=>loadCase(c.id));row.querySelector('[data-pdf]').addEventListener('click',async()=>{await loadCase(c.id);setTimeout(()=>openEditableReport(true),120)});row.querySelector('[data-word]').addEventListener('click',async()=>{await loadCase(c.id);setTimeout(()=>$('#wordBtn').click(),120)});row.querySelector('[data-excel]').addEventListener('click',async()=>{await loadCase(c.id);setTimeout(exportCurrentExcel,120)});row.querySelector('[data-send]').addEventListener('click',async()=>{await loadCase(c.id);await sendCurrentCase()});row.querySelector('[data-delete]').addEventListener('click',()=>deleteCase(c.id));host.appendChild(row)}if(!all.length)host.innerHTML='<div class="notice">No hay expedientes guardados.</div>'}
$('#refreshCasesBtn').addEventListener('click',renderCaseList);

async function lookupExistingCaseByTramite(value){
  const code=String(value||'').trim();if(!code||(!db&&storageMode!=='memory'))return false;
  const all=await idbAll(STORE_CASES);const found=all.find(x=>x.id!==state.current.id&&String(x.general?.tramite||'').trim().toLowerCase()===code.toLowerCase());
  if(!found)return false;
  if(!confirm(`Existe el expediente ${code}. ¿Desea cargar sus datos registrados?`))return false;
  state.current=normalizeCase(found);state.audit=Array.isArray(state.current.repositoryAudit?.items)?state.current.repositoryAudit.items:[];renderAll();showView('general');toast('Datos del inmueble completados desde la base local');return true;
}
document.addEventListener('change',e=>{if(e.target?.id==='tramiteLookup')lookupExistingCaseByTramite(e.target.value)});
function updateNetwork(){const on=navigator.onLine;$('#netDot').className=`dot ${on?'online':'offline'}`;$('#netText').textContent=on?'Con conexión':'Sin conexión'}
window.addEventListener('online',updateNetwork);window.addEventListener('offline',updateNetwork);
function isStandaloneMode(){return window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true}
function isMobileTabletDevice(){return Boolean(navigator.maxTouchPoints>0||window.matchMedia?.('(pointer:coarse)').matches||/Android|iPhone|iPad|Mobile|Tablet/i.test(navigator.userAgent))}
function refreshInstallUi(){const btn=$('#installBtn');if(!btn)return;if(isStandaloneMode()){btn.hidden=false;btn.disabled=true;btn.innerHTML='✓ <span>Instalada</span>';return}btn.hidden=false;btn.disabled=false;btn.innerHTML=deferredInstallPrompt?'⬇️ <span>Instalar</span>':'ℹ️ <span>Cómo instalar</span>'}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;refreshInstallUi()});
$('#installBtn').addEventListener('click',async()=>{if(isStandaloneMode())return;if(!deferredInstallPrompt){const ios=/iPhone|iPad|iPod/i.test(navigator.userAgent),mobile=isMobileTabletDevice();toast(ios?'En Safari pulse Compartir y luego “Agregar a pantalla de inicio”.':mobile?'Abra el menú del navegador y seleccione “Instalar aplicación” o “Agregar a pantalla principal”.':'En Chrome o Edge abra el menú del navegador y seleccione “Instalar Fiscalización B.I.”.');return}deferredInstallPrompt.prompt();const choice=await deferredInstallPrompt.userChoice;if(choice?.outcome==='accepted')toast('Instalación aceptada');deferredInstallPrompt=null;refreshInstallUi()});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;refreshInstallUi();toast('Aplicación instalada correctamente')});
window.matchMedia('(display-mode: standalone)').addEventListener?.('change',refreshInstallUi);
let serviceWorkerReloading=false;window.addEventListener('load',()=>{if(!('serviceWorker'in navigator)||!location.protocol.startsWith('http'))return;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(serviceWorkerReloading)return;serviceWorkerReloading=true;location.reload()});navigator.serviceWorker.register('./sw.js').then(reg=>{reg.update().catch(()=>{});refreshInstallUi()}).catch(console.warn)});

$('#newBtn').addEventListener('click',newCase);$('#saveBtn').addEventListener('click',()=>saveCase(false));
setInterval(()=>{$('#clock').textContent=new Date().toLocaleString('es-CR',{dateStyle:'medium',timeStyle:'medium'})},1000);

(async function init(){refreshInstallUi();updateNetwork();try{await openDb()}catch(e){storageMode='memory';console.warn('IndexedDB no disponible; se activa almacenamiento temporal:',e);setTimeout(()=>toast('Almacenamiento temporal: exporte respaldo JSON antes de cerrar'),500)}state.current=blankCase();renderAll();await renderCaseList()})();
